with feeders as (
    select
        md5(upper('HUB_POLICY|' || (HUB_POLICY_BK__POLICY_REF))) as HUB_POLICY_HK
        , CARD_SEND_TO_PERSON_NAME as DELIVERY_RECIPIENT_NAME
        , cast(null as varchar) as HEALTH_CARD_OPTION
