        , 'BJAZ_CARD_DTLS' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_card_dtls') }}
    where (nullif(trim(POLICY_REF),'')) is not null
    union all
    select
        md5(upper('HUB_POLICY|' || (HUB_POLICY_BK__POLICY_NO))) as HUB_POLICY_HK
        , cast(null as varchar) as DELIVERY_RECIPIENT_NAME
        , CARD_OPTION_AVAIL as HEALTH_CARD_OPTION
        , POLICY_DISP_DTLS as POLICY_DISPATCH_RECIPIENT_TYPE
        , POL_CONTACT_PERSON as POLICY_DISPATCH_CONTACT_PERSON
        , POL_ADDRESS as POLICY_DISPATCH_ADDRESS_TEXT
