        HUB_POLICY_HK,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then DELIVERY_RECIPIENT_NAME end) as DELIVERY_RECIPIENT_NAME,
        max(case when SOURCE_RUN = 'opus_health_v2' then HEALTH_CARD_OPTION end) as HEALTH_CARD_OPTION,
        max(case when SOURCE_RUN = 'opus_health_v2' then POLICY_DISPATCH_RECIPIENT_TYPE end) as POLICY_DISPATCH_RECIPIENT_TYPE,
