        max(case when SOURCE_RUN = 'opus_health_v2' then POLICY_DISPATCH_CONTACT_NUMBER end) as POLICY_DISPATCH_CONTACT_NUMBER,
        max(case when SOURCE_RUN = 'opus_health_v2' then HEALTH_CARD_DISPATCH_RECIPIENT_TYPE end) as HEALTH_CARD_DISPATCH_RECIPIENT_TYPE,
        max(case when SOURCE_RUN = 'opus_health_v2' then HEALTH_CARD_DISPATCH_CONTACT_PERSON end) as HEALTH_CARD_DISPATCH_CONTACT_PERSON,
        max(case when SOURCE_RUN = 'opus_health_v2' then HEALTH_CARD_DISPATCH_ADDRESS_TEXT end) as HEALTH_CARD_DISPATCH_ADDRESS_TEXT,
        max(case when SOURCE_RUN = 'opus_health_v2' then HEALTH_CARD_DISPATCH_CONTACT_NUMBER end) as HEALTH_CARD_DISPATCH_CONTACT_NUMBER,
