        *,
        case when DELIVERY_RECIPIENT_NAME is not null or HEALTH_CARD_OPTION is not null or POLICY_DISPATCH_RECIPIENT_TYPE is not null or POLICY_DISPATCH_CONTACT_PERSON is not null or POLICY_DISPATCH_ADDRESS_TEXT is not null or POLICY_DISPATCH_CONTACT_NUMBER is not null or HEALTH_CARD_DISPATCH_RECIPIENT_TYPE is not null or HEALTH_CARD_DISPATCH_CONTACT_PERSON is not null or HEALTH_CARD_DISPATCH_ADDRESS_TEXT is not null or HEALTH_CARD_DISPATCH_CONTACT_NUMBER is not null
                     then md5(upper(coalesce(cast(DELIVERY_RECIPIENT_NAME as varchar), '') || '|' || coalesce(cast(HEALTH_CARD_OPTION as varchar), '') || '|' || coalesce(cast(POLICY_DISPATCH_RECIPIENT_TYPE as varchar), '') || '|' || coalesce(cast(POLICY_DISPATCH_CONTACT_PERSON as varchar), '') || '|' || coalesce(cast(POLICY_DISPATCH_ADDRESS_TEXT as varchar), '') || '|' || coalesce(cast(POLICY_DISPATCH_CONTACT_NUMBER as varchar), '') || '|' || coalesce(cast(HEALTH_CARD_DISPATCH_RECIPIENT_TYPE as varchar), '') || '|' || coalesce(cast(HEALTH_CARD_DISPATCH_CONTACT_PERSON as varchar), '') || '|' || coalesce(cast(HEALTH_CARD_DISPATCH_ADDRESS_TEXT as varchar), '') || '|' || coalesce(cast(HEALTH_CARD_DISPATCH_CONTACT_NUMBER as varchar), '')))
                end as SAT_POLICY_DELIVERY_HASHDIFF
    from resolved
)

select * from hashed
